  "Every account is empty.": "所有账户都是空的。",
  "Every action keeps our customers moving forward.":
    "每一次操作，都让客户的货往前走一步。",
  "Every bill that has actually been raised is settled. Not the same as everything being billed.":
    "已开出的账单都已结清。这不等于所有货都已开单。",
  "Every case": "全部案件",
  "Every consignment": "全部货物",
  "every consignment has one": "每票货都有照片",
  "Every consignment in Dar, by what is holding it":
    "达累斯萨拉姆的每票货，按卡点分类",
  "Every cost recorded here becomes part of the profit figure — and one tied to a dispatch becomes part of that flight's.":
    "这里登记的每一笔成本都会计入利润；挂到某次发运上的，还会计入那一班的利润。",
  "Every deletion and restore is also written to the":
    "每一次删除和恢复也会写入",
  "Every desk, right now": "各岗位 · 实时",
  "Every detail matters.": "每一个细节都重要。",
  "Every dispatch on record": "全部发运记录",
  "Every dispatch that has left China. Open one to see its cargo, documents and full timeline.":
    "已离开中国的每一次发运。点开可看货物、单据和完整时间线。",
  "Every edit ever made to this record.": "该记录的全部修改历史。",
  "Every figure this business quotes comes from this page. Change it here and the whole system follows — cargo, invoices, tracking and reports.":
    "公司报出的每个数字都来自这个页面。在这里改，货物、账单、查件和报表全都跟着变。",
  "Every flagged item has been accounted for. Cargo flagged at check-in lands here on its own.":
    "所有标记的问题都已处理。入库核对时标记的货物会自动进到这里。",
  "Every handover this warehouse has made — what left, who took it, and who released it.":
    "本仓库的每一次交货记录——出库了什么、谁提的、谁放的货。",
  "Every individual customer's cargo.": "每一位客户的每一票货。",
  "Every invoice needs one": "每张账单都要用到",
  "Every item flagged missing, damaged or wrong on arrival — held here, with the boxes it belongs to, until someone closes it out.":
    "到货时标记为缺失、破损或错货的每一项，连同对应的箱子都留在这里，直到有人结案。",
  "Every landed batch is checked in": "已落地的批次都已核对入库",
  "Every money action on the system, who did it and when. Append-only — nothing here can be edited or removed, including by the CEO.":
    "系统里每一笔与钱有关的操作、谁做的、什么时候做的。只增不改——这里的记录谁都不能修改或删除，总经理也不行。",
  "Every movement of money — freight collected, costs paid, transfers between accounts — with its account, who recorded it, and a running balance.":
    "每一笔资金往来——收到的运费、支付的成本、账户间转账——都带上账户、登记人和累计余额。",
  "Every package accounted for": "每件都已核对",
  "Every package is on the floor. Scan the note, then the box.":
    "件数已全部在仓。先扫提货单，再扫箱子。",
  "Every payment received": "收到的全部款项",
  "Every payment says where it landed": "每笔收款都已注明入账账户",
  "Every payment, cost and transfer writes a line here as it happens.":
    "每一笔收款、成本和转账发生时都会在这里写下一行。",
  "Every piece accounted for or flagged": "每一件都已核对或已标记异常",
  "Every piece billed and confirmed": "每件都已开单并确认",
  "Every piece of cargo standing in the Dar warehouse right now — checked in, not yet handed over.":
    "此刻存放在达累斯萨拉姆仓库的每一票货——已入库核对，尚未交付。",
  "Every privileged action, newest first": "全部关键操作，最新在前",
  "Every question, complaint and request the desk has taken, and what happened next.":
    "客服台接到的每一个问题、投诉和申请，以及后续处理情况。",
  "Every quote in the system comes from this table. Nothing is hardcoded.":
    "系统里的每一笔报价都出自这张表，没有写死的价格。",
  "Every release recorded at the counter appears here, newest first, with the photo taken as the cargo changed hands.":
    "提货台登记的每一次放货都会显示在这里，最新在前，并附交接时拍的照片。",
  "Every shipment has a journey.": "每一票货都有它的旅程。",
  "Every shipment is settled — record a new one to try this flow.":
    "所有运单都已结清——新登记一票再来试这个流程。",
  "Every till and bank account, added up. Comes from the ledger, so it moves the moment money does.":
    "所有收银和银行账户的合计。数据来自账本，钱一动就变。",
  "Everyone still inside free storage": "全部仍在免费仓储期内",
  "Everything": "全部",
  "Everything currently in the database, with one-click ways to try each workflow.":
    "数据库里现有的全部数据，每个流程都能一键试用。",
  "Everything held is cleared": "在库货物全部已放行",
  "Everything inbound — in the air, on the floor, and being checked off. Oldest first; cargo on the floor comes before cargo in the air.":
    "所有到货情况——在飞的、已到场的、正在核对的。最早的在前；已到场的排在在飞的前面。",
  "Everything landed": "全部已落地货物",
  "Everything nobody has finished with": "所有还没处理完的事项",
  "Everything normally arrives as sent. Accept the whole manifest, then flag only what is missing or damaged.":
    "货物一般都按发出时的样子到达。先整批确认收货，再单独标记缺失或破损的。",
  "Everything on this bill is already known. Add the reference they sent and their receipt, and it goes to Finance to verify.":
    "这张账单的信息系统都有了。补上客户发来的参考号和收款凭证，提交财务核对。",
