  /*
    THE CARGO TYPES, in the language of the desk that types them.

    These are rows in CargoType, not literals in the source, so the dictionary
    never saw them — the Guangzhou desk got a form in Chinese with a product
    list in English underneath it, which is the one field on that form where
    picking wrong costs money: an unrecognised item is priced on the general
    rate. Keyed by the English name the row stores, like every other entry here,
    so a type added later shows in English until somebody adds its line rather
    than breaking the picker.
  */
