  "Nothing is ever destroyed. Every deletion is kept here with its reason, its photos and the person who made it.":
    "任何记录都不会真正销毁。每一次删除都连同原因、照片和操作人保留在这里。",
  "Nothing is owed. Every bill raised has been settled.":
    "没有欠款。开出的账单都已结清。",
  "Nothing is settled until Finance verifies it. No money moves on this screen.":
    "财务核实前不算结清。本页面不涉及资金变动。",
  "Nothing is standing on the floor.": "现场没有存货。",
  "Nothing is waiting in Guangzhou.": "广州没有滞留货物。",
  "Nothing is waiting on the floor.": "现场没有待处理的货。",
  "Nothing is waiting on this desk. Every consignment is photographed, on a batch, and moving.":
    "本岗没有待办。每票货都已拍照、已进批次、正在流转。",
  "Nothing is waiting on this floor. Every batch is checked in, nothing is short, and no case is open.":
    "本仓没有待办。批次都已核对入库，没有短少，也没有未结案件。",
  "Nothing is waiting on you. Every bill sent is settled, nothing has been sent back, and no claim is outstanding.":
    "没有待你处理的事。发出去的账单都已结清，没有被退回的，也没有未了结的付款申报。",
  "Nothing is waiting on you. Every landed consignment is billed and no customer is owed a call.":
    "没有待你处理的事。每票到货都已开单，也没有客户等着我们回电。",
  "Nothing is waiting on you. Every price is confirmed, every payment sits in an account, and every bill has been settled.":
    "没有等你处理的事。价格都已确认，每笔收款都已入账，账单都已结清。",
  "Nothing is waiting. Every price is confirmed, every payment says where it landed, and nothing is owed either way.":
    "没有待办。价格都已确认，每笔收款都已说明入账账户，也没有任何欠款。",
  "Nothing is with Finance.": "财务处没有待处理的款项。",
