  "Flight details": "航班信息",
  "Fill in whatever the airline has given you. Anything still unknown can stay empty and be added later — the cargo does not wait for it.":
    "航空公司给到什么就填什么。尚未确定的可以留空，之后再补——货物不必等它。",
  "Leave it empty until the airline issues it.": "在航空公司出单之前请留空。",
  "The day it really left, not the day it was booked for.": "实际起飞的日期，而不是原定的日期。",
  "What changed": "改动了什么",
  "Airline moved the flight to the 25th": "航空公司把航班改到了 25 号",
  "Save flight details": "保存航班信息",
  "Missing flight.": "缺少航班。",
  "That flight no longer exists.": "该航班已不存在。",
  "A loading table has no flight details until it is dispatched.":
    "装货批次在发运之前没有航班信息。",
  "is closed and its statement is frozen. Reopen it before changing the flight.":
    "已关闭且结算单已冻结。如需更改航班信息，请先重新开启。",
  "This flight was closed a moment ago. Reload before changing it.":
    "此航班刚刚被关闭。修改前请刷新。",
  "Priced at check-in": "入库核对时计价",
  "This cargo has not been checked in at Dar yet, so there is no final weight to price it on. The bill is raised by the system the moment the warehouse checks it off the manifest.":
    "此货物尚未在达累斯萨拉姆入库核对，因此没有可用于计价的最终重量。仓库在清单上核对完成的那一刻，系统会自动生成账单。",
  "has not been checked in at Dar yet, so there is no final weight to price. The system raises the bill by itself the moment the warehouse checks it off the manifest.":
    "尚未在达累斯萨拉姆入库核对，因此没有最终重量可用于计价。仓库在清单上核对完成的那一刻，系统会自动生成账单。",
  "Cancel the bill": "取消账单",
  "Why is this bill being cancelled?": "为什么要取消这张账单？",
  "is cancelled. The cargo will be priced again when Dar checks it in.":
    "已取消。货物将在达累斯萨拉姆入库核对时重新计价。",
  "The bill is removed and the cargo goes back to having no price. It will be priced again from the rate book when Dar checks it in. Who cancelled it, and why, stays on the audit log.":
    "账单将被删除，货物恢复为未计价状态。达累斯萨拉姆入库核对时会按价目表重新计价。谁取消的、为什么取消，都会留在审计日志中。",
  "This price was never signed off, so nobody has been asked for it. The cargo goes back to having no bill and will be priced again when Dar checks it in.":
    "此价格从未确认，因此没有向任何人收取。货物恢复为无账单状态，达累斯萨拉姆入库核对时会重新计价。",
  "That bill no longer exists.": "该账单已不存在。",
  "Say why this bill is being cancelled.": "请说明取消这张账单的原因。",
  "Keep the reason under 500 characters.": "原因请控制在 500 字以内。",
  "This price has already been confirmed, so only the owner can cancel the bill. Ask him, or correct the figure instead.":
    "此价格已确认，只有老板可以取消账单。请联系他，或改为修正金额。",
  "was written off when its flight closed. That decision is part of a closed statement.":
    "在其航班关闭时已被核销。该决定属于已关闭的结算单。",
  "has money recorded against it. Cancel the payment first — then the bill can go.":
    "已有款项记录在该账单上。请先取消付款，然后才能取消账单。",
  "is still standing on this cargo, so it is cleared to leave. Cancel the pickup note first.":
    "此货物仍有有效的提货单，已获准提走。请先取消提货单。",
  "is closed and its statement is frozen. Reopen it before changing what it billed.":
    "已关闭且结算单已冻结。如需更改其账单内容，请先重新开启。",
  "This bill changed a moment ago. Reload and look at it again before cancelling.":
    "此账单刚刚发生了变动。取消之前请刷新并重新查看。",
  "Approving authorises a payout on this case. Finance records the amount afterwards — the figure is theirs, the decision is yours.":
    "批准即授权本案的赔付。之后由财务记录金额——数字归财务，决定权在您。",
  "Money that has gone out must name the account it left. Pick one under \"Paid from\".":
    "已经付出去的钱必须注明是从哪个账户支出的。请在\u201C付款账户\u201D中选择一个。",
  "Pick the payment date first — the account records where the money left on that day.":
    "请先选择付款日期——账户记录的是钱在那一天从哪里支出。",
  "Required once a payment date is set — it puts the payout on the general ledger against this account.":
    "填写付款日期后必填——赔偿金将以此账户记入总账。",
  "A bill on this flight was paid while you were closing it. Reload and close again with the fresh figures.":
    "在您关闭此航班时，其中一张账单刚被支付。请刷新后用最新数字重新关闭。",
  "Somebody closed this flight a moment ago. Reload to see their close.":
    "刚刚有人关闭了此航班。请刷新查看他们的关闭结果。",
  "This bill's balance moved a moment ago. Reload and check it before reinstating.":
    "此账单的余额刚刚发生了变动。恢复之前请刷新并核对。",
  "This bill's balance moved a moment ago. Reload and check it before cancelling.":
    "此账单的余额刚刚发生了变动。作废之前请刷新并核对。",
  "The credit on this bill was just decided by somebody else. Reload to see where it stands.":
    "此账单的赊账刚被他人处理。请刷新查看其当前状态。",
  "That date is before the bill was raised. A payment cannot be older than the invoice it settles.":
    "该日期早于账单开出的日期。付款不能早于它所结清的账单。",
  "Currency must be TZS or USD.": "币种必须是 TZS 或 USD。",
  "A payout cannot be dated in the future.": "赔付日期不能是未来的日期。",
  "A cost cannot be dated in the future.": "支出日期不能是未来的日期。",
  "That date is not valid.": "该日期无效。",
  "That name is too long.": "名称过长。",
  "Keep the description under 500 characters.": "描述请控制在 500 字以内。",
  "Keep internal notes under 1000 characters.": "内部备注请控制在 1000 字以内。",
  "That reference is too long.": "参考号过长。",
  "Keep the note under 1000 characters.": "备注请控制在 1000 字以内。",
  "Only the person who submitted this can correct it. Ask them to, or let Finance decide it as it stands.":
    "只有提交人本人才能更正。请让提交人修改，或由财务按原样处理。",
  "No markets in the directory yet": "目录中还没有市场",
  "Once the directory is written, every market appears here with what it sells and how it flies home.":
    "目录建立后，每个市场都会显示在这里，包括其经营的商品和发货航线。",
  "No markets yet": "还没有市场",
  "The first one you add appears on the support desk and the public guide.":
    "您添加的第一个市场会出现在客服台和公开指南中。",
  "Something went wrong. Please message us on WhatsApp instead.":
    "出了点问题。请改用 WhatsApp 联系我们。",
  /*
    THE PHRASES BEHIND A COMPUTED KEY.

    `t(phrase)` passes a value, so check-i18n cannot see any of these — and a
    hundred of them were rendering to Guangzhou in English: the whole manager
    operations panel, every "what to do next" line on the collections queue,
    the reconciliation states, the reviewer's action blurbs. scripts/
    check-computed-i18n.mjs finds them now.
  */
