  "Anything the manager should know": "需要让经理知道的事项",
  "Apart by": "相差",
  "Append-only. Nothing here can be edited or removed.": "只增不改。这里的记录不能编辑或删除。",
  "Apply": "应用",
  "Approvals": "审批",
