  "Asked for and waiting on a decision. Nothing to do but watch.": "已提交申请，等待审批。目前只需等待。",
  "Attendance is not tracked. Opened the app today means exactly that, and nothing more.": "系统不记考勤。“今天打开过应用”只表示这一点，别无他意。",
