  "Billed this month · cash against credit": "本月开单 · 现结对比赊账",
  "Billed today": "今日开单",
  "Billed value, counting a written-off bill in full. It will not total to Revenue above, which counts one at what was paid before it was given up on.": "账单总额，已核销的账单按全额计入。它不会与上方的收入吻合——收入里核销账单只按放弃前实收的金额计。",
  "Books last closed": "上次关账",
  "Build it from the staff register": "从员工名册生成",
