  "Business volume": "业务量",
  "By expense category": "按支出类别",
  "By origin": "按始发地",
  "Calculated": "计算值",
  "Call them": "打电话联系",
  "Cancel the movement": "撤销这笔资金变动",
  "Cancel the payment": "撤销这笔付款",
  "Cancel this cost — it should never have been recorded": "撤销此项成本——本就不该记录",
  "Cancel this movement": "撤销此笔资金变动",
  "Cancel this payment": "撤销此笔付款",
  "Cancelled & deleted": "已撤销并删除",
  "Cancelled money": "已撤销的款项",
  "Cancels": "撤销",
  "Cargo cannot be carried onto the batch it is already on.": "货物不能转到它当前所在的批次。",
  "Cargo in motion": "在途货物",
  "Cargo landed, by month": "落地货物，按月",
  "Cargo released before payment. None of this is cash — it is money customers still owe, and the oldest debt is the one to ring about.": "付款前已放行的货物。这些都不是现金——是客户仍欠的钱，最久的欠款最该打电话催。",
  "Cargo released on credit is": "赊账放行的货物共",
  "Carried kg": "承运公斤数",
  "Carry that cargo to": "将该货物转到",
  "Cash is the tins and tills. There is no separate petty-cash pot in this system — petty cash is a cash account, and it is counted above.": "现金指钱箱和收银台里的钱。系统里没有单独的备用金池——备用金也是一个现金账户，已计入上方数字。",
  "Cash owed": "现结欠款",
  "Cash sale": "现结销售",
  "Change limit": "修改额度",
  "Change or extend the due date": "修改或延长到期日",
  "Charge it after all": "仍然收取此项费用",
  "Chased three times, no answer": "已催三次，无回应",
  "Check every piece off the manifest before closing the books on this batch.": "对照舱单核对每一件货物，再为本批次关账。",
  "Check this account": "核查此账户",
  "Choose a batch…": "选择批次…",
  "Choose a cash account and the money leaves the tin as you record it. Attach the receipt here rather than keeping it in a pocket.": "选择一个现金账户，记录的同时钱即从钱箱扣出。收据请附在这里，不要揣在口袋里。",
  "Choose a date, or one of the terms.": "选择一个日期，或选择其中一个期限。",
  "Choose the account": "选择账户",
  "Choose the batch this cargo is moving to.": "选择这票货物要转入的批次。",
  "Clear the filters": "清除筛选",
  "Clear the search": "清除搜索",
  "Clear:": "清除：",
  "Close the books": "结账",
  "Close this batch anyway": "仍然关闭此批次",
  "Close without moving it": "不转移，直接关闭",
  "Closing": "正在关闭",
  "Collect": "收款",
  "Collected against billed": "已收款与已开账对比",
  "Collected and Expenses are money that has actually moved. The rest is what this batch is expected to be worth once everyone pays.": "“已收款”和“支出”是实际已发生的资金流动。其余部分是等所有人付清后，此批次预计的价值。",
  "Collected today": "今日已收款",
  "Collected — the clock stopped": "已收款 — 计时已停止",
  "Collecting well": "收款情况良好",
  "Collection performance": "收款表现",
  "Collection rate": "收款率",
  "Confirm it or send it back.": "确认，或退回。",
  "Confirm the price first — credit cannot be granted against a figure nobody has signed off.": "请先确认价格 — 未经确认的金额不能授予赊账。",
  "Confirm the price on every piece first — closing now would give up money nobody has been asked for.": "请先确认每件货物的价格 — 现在关闭会放弃尚未向任何人收取的款项。",
  "Confirmed": "已确认",
  "Confirming makes this the final word on the batch. Sending it back reopens it so Finance can fix what is wrong.": "确认后，此结果即为该批次的最终定论。退回则重新打开批次，让财务修正问题。",
  "Consignments registered, month by month": "逐月登记的货物",
  "Correct": "更正",
  "Correct the details": "更正详细信息",
  "Correct the lines below and send it up again. Last time's ruling is dropped the moment it goes.": "更正下面的条目后重新提交。一经提交，上次的裁定即作废。",
