  "Credit requested — waiting on Finance": "已申请赊账 — 等待财务审批",
  "Credit revenue is inside Revenue above, because the sale happened. It is not in Collected, and none of it is in the bank.": "赊账收入已计入上方的“收入”，因为销售已经发生。但它不在“已收款”中，也没有一分钱进入银行。",
  "Credit · released before payment": "赊账 · 付款前已放货",
