  "after that": "此后",
  "agreed": "已核对一致",
  "agreed by": "核对确认人：",
  "already covers that month. Open it instead of building a second one.": "已涵盖该月份。请直接打开它，不要再新建一份。",
  "already overdue on": "已逾期，逾期日期：",
