    "该记录已存在。请刷新页面确认后再试。",
  "That record no longer exists. Somebody may have changed it while this page was open.":
    "该记录已不存在。可能有人在此页面打开期间做了修改。",
  "The batch is chosen for you from the cargo type — you never pick it.":
    "批次由货物类别自动确定，无需手动选择。",
