    "已询问客户希望如何处理。",
  "The customer has been told what they owe and the money has not arrived. This is the call list.":
    "已经告诉客户欠多少钱，但钱没到。这就是催款名单。",
  "The damage itself, and the label, so the case can be matched to the carton later.":
    "破损本身和标签都要拍，日后才能把案件和具体箱子对上。",
  "The database refused that change. Refresh the page and try again.":
    "数据库拒绝了此次修改。请刷新页面后重试。",
