  "Leave this blank — it is recorded as happening right now. Only set it when backdating a cost found later.": "留空即可——系统会记录为此刻发生。仅在补记一笔后来才发现的旧费用时才需要填写日期。",
  "Almost everything is Operating — leave it as it is. Special is only for something like an owner's personal draw, which should not count as a running cost of the business.": "绝大多数成本都是「日常经营」，保持默认即可。「特殊」仅用于类似老板个人支取这类不应计入公司日常运营成本的情况。",
