    "现金盒里实际有多少，与账面应有金额核对。",
  "What is standing now": "当前在库情况",
  "What the business is holding, what is owed to it, and what has moved. Shown in shillings; the dollar figure is what the invoice says.":
    "公司在手的钱、别人欠的钱，以及资金的进出。以坦先令显示；美元数字是账单上的金额。",
  "What the business spends, and what it has already paid. Costs are dated when they were incurred; the money is dated when it left.":
    "公司花了多少、已经付了多少。成本按发生日期计，钱按支出日期计。",
  "What the China desk can pick from, and what customers see in the calculator. A product with no price still cannot be quoted.":
    "中国收货台可以选择的商品，也是客户在运费计算器里看到的商品。没有价格的商品仍然无法报价。",
  "What the customer said": "客户怎么说",
