  "You have not registered any cargo yet.": "你还没有登记过货物。",
  "You opened this cargo from a list, so the box itself has not been read yet.":
    "这票货是从列表打开的，箱子本身还没有扫过。",
  "You opened this from the unreadable-label list. Check the tracking number against the customer's paperwork yourself, and make sure the cargo is in the handover photograph — that photo is the only record that the right box left the building.":
    "你是从标签读不出的名单里打开的。请自己拿运单号和客户的单据核对，并确保货物出现在交接照片里——那张照片是箱子没发错的唯一凭证。",
  "You scanned box": "你扫的是第",
  "You will hear about batches leaving China, cargo of yours that a manager edited, and company announcements.":
    "批次离开中国、管理员改动了你经手的货物、公司公告，都会在这里通知你。",
  "Your account no longer exists.": "你的账号已不存在。",
  "Your actions, newest first": "你的操作记录，最新在前",
  "Your activity": "我的工作量",
  "Your browser blocked clipboard access.": "浏览器阻止了剪贴板访问。",
  "Your cargo reaches Tanzania in 3-10 days.": "货物 3-10 天到达坦桑尼亚。",
  "Your changes are recorded with your name against them. Management can read the full history.":
    "你的修改会连同你的名字一起记录。管理层可以查看完整记录。",
  "Your dashboard opens automatically based on your department.":
    "系统会按你的部门自动打开对应工作台。",
  "Your last two weeks": "你的最近两周",
  "Your name": "你的姓名",
  "Your own words. The customer sees this when they track.":
    "你自己写的说明。客户查件时会看到。",
  "Your own words. This is what the customer sees when they track, and what appears on the invoice.":
    "用你自己的话写。客户查件时看到的就是这句，发票上也用它。",
  "Your packages": "你的件数",
  "Your part comes if a payout is approved: you record what actually goes out.":
    "赔付获批后才轮到你：由你登记实际付出的金额。",
  "Your profile photo": "你的头像",
