  "Your weight": "你的收货重量",
  "Your work": "你的工作",
  "Yours to change. Anything about your employment is set by management.":
    "这些你可以自己改。与聘用相关的内容由管理层设定。",
  "· attached to this case": "· 已附到本案件",
  "· no phone": "· 无电话",
  "· no phone on file": "· 未登记电话",
  "— add one to their profile to message them.":
    "—— 请先在其客户资料里补上电话，才能给他发消息。",
  "— no opening balance has been set, so whatever was already in it is not counted.":
    "——尚未设置期初余额，账户中原有的金额未计入。",
  "— not the customer in person": "条中，非客户本人提取",
  "— shipment label": "— 运单标签",
  "— storage runs the whole time the cargo is on our floor.":
    "——货在我们仓库的每一天都在产生仓储费。",
  "— that is": "—— 相差",
  "— that matches.": "—— 与账面相符。",
  "— the rest is in the warehouse.": "—— 其余在仓库里。",
  "’s record.": "的客户档案。",
  "’s running balance": "的滚动余额",
  "“Issue pickup note” unlocks once it is settled. That is the only thing that moves cargo to Ready for pickup.":
    "结清后“开具提货单”才会解锁。只有它能把货物变成“可提货”。",
  "“Scan this” opens the scanner with the code already resolved. “Copy” puts the raw QR payload on your clipboard so you can paste it into the release screen's manual field.":
    "“扫这个”会打开扫码页并直接带上该二维码。“复制”会把原始二维码内容复制到剪贴板，方便粘贴到放货页的手动输入栏。",
