    "批次长期不封就不再是批次，而变成了货架。",
  "A case that is": "当前状态为",
  "A claim on this shipment is being processed. We will contact you with the outcome.":
    "该运单的索赔正在处理中，结果会通知您。",
  "A collection deadline.": "提货期限。",
  "A damaged-cargo exception records what was damaged, never what it was worth, so any figure would be invented.":
    "破损异常只记录破损了什么，不记录价值，因此任何金额都是编出来的。",
  "A fixed per-item price has to name the product it applies to.":
    "按件固定价必须指明适用的商品。",
  "A phone number is required.": "必须填写电话号码。",
  "A week is counted on the date each shipment was checked in against its manifest, and each release on the date it was handed over. Independent of the period switch above.":
    "每票货按其对照舱单核收的日期计入当周，放货按实际交付日期计入。与上方时间段选择无关。",
