  "Days held": "在仓天数",
  "Delete it first. Permanent removal only applies to records already in Deleted records.":
    "请先删除。永久移除仅适用于已在“已删除记录”中的数据。",
  "Departure date is not valid.": "起飞日期无效。",
  "Do not release this cargo — send the customer to Finance to find out why.":
    "请勿放货——让客户去财务了解原因。",
