  "Money we hold that nobody has said where it landed.":
    "我们收到的钱，但没人说清进了哪个账户。",
  "No active rate covers that cargo yet. Ask the CEO to publish one, or message us for a quote.":
    "暂无适用于该货物的有效费率。请让总经理发布费率，或联系我们询价。",
