  "Nothing flagged": "无异常",
  "Nothing is being held at the Dar warehouse.": "达市仓库目前没有在存货物。",
  "Nothing to show a customer whose cargo arrives damaged, and nothing to argue with when they say it did.":
    "客户货物到货破损时无凭可示，客户说破损时也无据可依。",
